#!/usr/bin/env python3
import os
import re
from datetime import datetime

def get_last_tag():
    """Get the most recent tag reachable from HEAD"""
    try:
        result = os.popen("git describe --tags --abbrev=0 2>&1").read().strip()
        return result if result else None
    except Exception:
        return None

def get_commits_between(tag_name):
    """
    Get commits between tag and HEAD.
    Returns list of dicts with hash, subject, body, files list.
    """
    commits = []
    if not tag_name:
        ref = ""  # All history
    else:
        ref = f"{tag_name}..HEAD"

    # Get all commit hashes
    hashes = os.popen(f"git log {ref} --pretty=format:%H").read().strip().splitlines()

    for commit_hash in hashes:
        # Get subject line
        subject = os.popen(f"git log -n 1 --pretty=format:%s {commit_hash}").read().strip()
        # Get body
        body = os.popen(f"git log -n 1 --pretty=format:%b {commit_hash}").read().strip()
        # Get changed files
        files = []
        try:
            files_content = os.popen(f"git show --name-only --pretty=format: {commit_hash}").read().strip()
            files = [f.strip() for f in files_content.splitlines() if f.strip()]
        except Exception:
            pass
        commits.append({
            'hash': commit_hash,
            'subject': subject,
            'body': body,
            'files': files
        })
    return commits

def parse_commit_message(msg):
    """
    Parse commit message like "feat(utils): description"
    Returns (type, scope, description) or None if doesn't match format
    """
    msg = msg.strip()
    match = re.match(r'^(\w+)\(([^)]+)\):\s*(.*)$', msg)
    if match:
        type_val = match.group(1)
        scope = match.group(2)
        description = match.group(3).strip()
        if type_val in ('feat', 'fix'):
            return (type_val, scope, description)
    return None

def parse_version(version_str):
    """Parse version string like '1.0.0' into tuple of ints"""
    parts = version_str.strip().split('.')
    try:
        return (int(parts[0]), int(parts[1]), int(parts[2]))
    except:
        return (0, 0, 0)

def bump_version(version_str, bump_type):
    """
    bump_type: 'major', 'minor', 'patch'
    Returns new version string
    """
    parts = parse_version(version_str)
    if bump_type == 'major':
        parts = (parts[0] + 1, 0, 0)
    elif bump_type == 'minor':
        parts = (parts[0], parts[1] + 1, 0)
    elif bump_type == 'patch':
        parts = (parts[0], parts[1], parts[2] + 1)
    return f"{parts[0]}.{parts[1]}.{parts[2]}"

def main():
    # Find last tag
    tag_name = get_last_tag()

    # Get commits
    commits = get_commits_between(tag_name)

    # Read current versions of all packages
    package_versions = {}  # name -> current version string
    all_packages = []  # names of packages that have VERSION file
    if os.path.isdir("/app/packages"):
        for name in os.listdir("/app/packages"):
            path = f"/app/packages/{name}/VERSION"
            if os.path.exists(path):
                with open(path, 'r') as f:
                    content = f.read().strip()
                    package_versions[name] = content
                    all_packages.append(name)

    # Direct bump from own commits: direct_bump[pkg] = 'major'/'minor'/'patch' or None
    direct_bump = {}  # only stores bump level if there was at least one direct commit
    # Also track direct entries for changelog: what feat/fix descriptions came from direct commits
    pkg_direct_entries = {}  # package -> list of {'type': 'feat'|'fix', 'description': 'text'}

    for commit in commits:
        parsed = parse_commit_message(commit['subject'])
        if not parsed:
            continue
        type_val, scope, description = parsed

        # Find all packages affected by this commit (files under packages/<name>/)
        affected_pkgs = []
        for f in commit['files']:
            if f.startswith("packages/"):
                parts = f.split("/")
                if len(parts) >= 2 and parts[0] == "packages":
                    pkg_name = parts[1]  # The package name after "packages/"
                    if pkg_name not in affected_pkgs:
                        affected_pkgs.append(pkg_name)

        # For each affected package, this is a direct change
        for pkg in affected_pkgs:
            # Determine bump level for this package from this commit
            bump = None
            if "BREAKING CHANGE" in description:
                bump = "major"
            elif type_val == "feat":
                bump = "minor"
            elif type_val == "fix":
                bump = "patch"

            # Record this direct change for changelog
            if pkg not in pkg_direct_entries:
                pkg_direct_entries[pkg] = []
            pkg_direct_entries[pkg].append({
                'type': type_val,
                'description': description,
                'bump': bump
            })

            # Update direct_bump to highest seen so far
            if pkg not in direct_bump:
                direct_bump[pkg] = bump
            else:
                levels = {'major': 3, 'minor': 2, 'patch': 1, None: 0}
                if levels.get(bump, 0) > levels.get(direct_bump[pkg], 0):
                    direct_bump[pkg] = bump

    # Read deps.txt files
    deps_of = {}  # package -> list of packages it depends on
    if os.path.isdir("/app/packages"):
        for name in os.listdir("/app/packages"):
            path = f"/app/packages/{name}/deps.txt"
            if os.path.exists(path):
                with open(path, 'r') as f:
                    content = f.read().strip()
                    deps_of[name] = [line.strip() for line in content.splitlines() if line.strip()]

    # Determine all packages that are "bumped" (direct or propagated)
    # bumped_set contains all packages that will have version changes
    bumped_set = set()
    # Initially add packages that have direct bumps
    for pkg in direct_bump:
        if direct_bump[pkg] is not None:
            bumped_set.add(pkg)

    # Propagate: recursively add dependents
    changed = True
    while changed:
        changed = False
        for pkg in list(bumped_set):
            # Find packages that depend on pkg (i.e., have pkg in their deps_of)
            for other in all_packages:
                if pkg in deps_of.get(other, []):
                    if other not in bumped_set:
                        bumped_set.add(other)
                        changed = True

    # Compute final bump for each package
    final_bump = {}  # package -> bump level string or None
    for pkg in all_packages:
        if pkg in direct_bump and direct_bump[pkg] is not None:
            final_bump[pkg] = direct_bump[pkg]  # direct bump takes precedence
        elif pkg in bumped_set:
            # Has propagation bump but no direct bump
            final_bump[pkg] = 'patch'
        else:
            final_bump[pkg] = None  # no change

    # Generate outputs
    today = datetime.now().strftime("%Y-%m-%d")

    # First update all VERSION and CHANGELOG files
    for pkg in all_packages:
        # Determine new version
        if final_bump[pkg] is None:
            new_version = package_versions[pkg]  # unchanged
        else:
            new_version = bump_version(package_versions[pkg], final_bump[pkg])

        # Update VERSION file
        with open(f"/app/packages/{pkg}/VERSION", 'w') as f:
            f.write(new_version + "\n")

        # Generate CHANGELOG.md
        changelog_lines = []
        changelog_lines.append(f"## {new_version} ({today})")

        # Collect feat and fix entries from direct commits only
        features = []
        fixes = []
        if pkg in pkg_direct_entries:
            for entry in pkg_direct_entries[pkg]:
                if entry['type'] == 'feat':
                    features.append(entry['description'])
                elif entry['type'] == 'fix':
                    fixes.append(entry['description'])

        if features:
            changelog_lines.append("### Features")
            for desc in features:
                changelog_lines.append(f"- {desc}")
        if fixes:
            changelog_lines.append("### Bug Fixes")
            for desc in fixes:
                changelog_lines.append(f"- {desc}")

        # Dependencies section only if bumped ONLY due to dependencies (no direct commits)
        # That means pkg had no direct commits at all (not in pkg_direct_entries)
        if pkg not in pkg_direct_entries:
            changelog_lines.append("### Dependencies")
            changelog_lines.append("- update dependencies")

        with open(f"/app/packages/{pkg}/CHANGELOG.md", 'w') as f:
            f.write("\n".join(changelog_lines) + "\n")

    # Generate root release-notes.md
    with open("/app/release-notes.md", 'w') as f:
        f.write("# Release Notes\n")
        for pkg in all_packages:
            f.write(f"\n## {pkg}\n")
            # List feat and fix entries from direct commits
            if pkg in pkg_direct_entries:
                for entry in pkg_direct_entries[pkg]:
                    prefix = "[feat]" if entry['type'] == 'feat' else "[fix]"
                    f.write(f"- {prefix} {entry['description']}\n")
            # Add [deps] if package had no direct commits but was bumped due to dependencies
            if pkg not in pkg_direct_entries and final_bump[pkg] == 'patch':
                f.write("- [deps] update dependencies\n")

    print("Done generating changelogs.")

if __name__ == "__main__":
    main()
